import SwiftUI
struct BalanceReportItem:Codable,Identifiable,Sendable{let id:UUID;let name:String;let accountType:String;let currencyCode:String;let balance:String}
struct ReportsView:View{@EnvironmentObject var session:SessionStore;@State private var balances:[BalanceReportItem]=[];@State private var exportURL:URL?
 var body:some View{NavigationStack{List{Section("Hesap Bakiyeleri"){ForEach(balances){item in HStack{Text(item.name);Spacer();Text((try? Money(item.balance).formatted(currency:item.currencyCode)) ?? item.balance)}}}Section("Diğer Raporlar"){Label("Gelir / Gider",systemImage:"chart.bar");Label("Kategori Dağılımı",systemImage:"chart.pie");Label("Borçlar ve Alacaklar",systemImage:"person.2")}}.navigationTitle("Raporlar").toolbar{if let exportURL{ShareLink(item:exportURL){Image(systemName:"square.and.arrow.up")}}}.task(id:session.selectedBook?.id){await load()}}}
 func load()async{guard let id=session.selectedBook?.id else{return};do{let page:Page<BalanceReportItem>=try await session.container.api.get("reports/balances",query:[.init(name:"bookId",value:id.uuidString)]);balances=page.items;let data=PDFReportRenderer.render(title:"Hesap Bakiyeleri",lines:balances.map{"\($0.name): \($0.balance) \($0.currencyCode)"});let url=FileManager.default.temporaryDirectory.appendingPathComponent("account-balances.pdf");try data.write(to:url,options:.atomic);exportURL=url}catch{}}
}
